import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.mzJ8I8R4.js";const u=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),o={name:"guide/index.md"};function l(i,t,n,h,s,p){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>NextTodo 是一个待办应用。和普通待办不同的是，事项之间可以设置先后：“建好官网”完成后才能“写官网文档”。NextTodo 据此只把现在能做的事列在“接下来”里，完成一项，它解锁的事项随即出现。</p><h2 id="_1-安装-app" tabindex="-1">1. 安装 App <a class="header-anchor" href="#_1-安装-app" aria-label="Permalink to &quot;1. 安装 App&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>下载</th><th>要求</th></tr></thead><tbody><tr><td>Android</td><td><a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-android.apk" target="_blank" rel="noreferrer">NextTodo-android.apk</a></td><td>Android 8.0 及以上</td></tr><tr><td>macOS</td><td><a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-macos-arm64.dmg" target="_blank" rel="noreferrer">NextTodo-macos-arm64.dmg</a></td><td>Apple 芯片，macOS 14 及以上</td></tr><tr><td>Windows</td><td><a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-windows-x64-setup.exe" target="_blank" rel="noreferrer">NextTodo-windows-x64-setup.exe</a></td><td>Windows 10 或 11，x64</td></tr></tbody></table><p>链接下载的都是最新版。第一次打开时系统可能会拦下，处理办法见<a href="./install">下载和安装</a>。</p><h2 id="modes" tabindex="-1">2. 选择用法 <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;2. 选择用法 {#modes}&quot;">​</a></h2><p>第一次打开 App 时，要在两种用法之间选一种：</p><table tabindex="0"><thead><tr><th></th><th>在本机使用</th><th>连接服务器</th></tr></thead><tbody><tr><td>适合</td><td>只在一台设备上使用</td><td>在多台设备之间同步，或使用网页版</td></tr><tr><td>需要</td><td>只需安装 App</td><td>一台自己的服务器、一个域名和 HTTPS 证书</td></tr><tr><td>账号</td><td>不需要</td><td>用户名和密码</td></tr><tr><td>数据存放</td><td>这台设备上，可以备份和恢复</td><td>自己的服务器上，各设备各有一份副本</td></tr></tbody></table><ul><li><strong>在本机使用</strong>：点击“在本机使用”即可开始，适合先试用。详见<a href="./local">在本机使用</a>。</li><li><strong>连接服务器</strong>：先按<a href="./server">部署服务器</a>准备好服务器，再点击“连接服务器”，填写服务器地址、用户名和密码登录。</li></ul><p>两种用法的数据互不相通。先在本机使用、以后改用服务器也可以，但本机的数据不会自动搬过去。</p><h2 id="_3-开始使用" tabindex="-1">3. 开始使用 <a class="header-anchor" href="#_3-开始使用" aria-label="Permalink to &quot;3. 开始使用&quot;">​</a></h2><ol><li>在添加框里写下一件事，按回车。添加框在手机屏幕底部，电脑上在标题下方。</li><li>点开这一项，在“前置”里选出要先完成的事项。</li><li>回到“接下来”，那里只列出现在能做的事。</li></ol><p>详见<a href="./basics">基本用法</a>。</p><h2 id="_4-更多" tabindex="-1">4. 更多 <a class="header-anchor" href="#_4-更多" aria-label="Permalink to &quot;4. 更多&quot;">​</a></h2><ul><li><a href="./ai">AI 整理</a>：把一大段话交给 AI，整理成带先后关系的事项。</li><li><a href="./agent">接入 agent</a>：让 Claude Code、Codex 这类 AI 助手直接管理待办。</li></ul>',15)])])}const x=e(o,[["render",l]]);export{u as __pageData,x as default};
